package com.andye.warmod.antiair;import java.util.SplittableRandom;import net.minecraft.world.phys.Vec3;public final class AntiAirGuidanceResolver{private AntiAirGuidanceResolver(){}public static double maximumMiss(int tier){return switch(Math.max(0,Math.min(3,tier))){case 1->15;case 2->10;case 3->0;default->20;};}public static AntiAirGuidanceResolution resolve(AntiAirGuidanceProfile p,Vec3 routeTangent){double max=maximumMiss(p.guidanceTier());if(max==0)return new AntiAirGuidanceResolution(3,p.perfectInterceptPosition(),Vec3.ZERO,0);Vec3 normal=p.targetVelocityAtIntercept().lengthSqr()>1e-8?p.targetVelocityAtIntercept().normalize():(routeTangent.lengthSqr()>1e-8?routeTangent.normalize():new Vec3(0,0,1));Vec3 a=Math.abs(normal.y)<.9?normal.cross(new Vec3(0,1,0)).normalize():normal.cross(new Vec3(1,0,0)).normalize(),b=normal.cross(a).normalize();SplittableRandom r=new SplittableRandom(p.guidanceSeed());double x=(r.nextDouble()+r.nextDouble()+r.nextDouble()-1.5)/1.5,y=(r.nextDouble()+r.nextDouble()+r.nextDouble()-1.5)/1.5;double length=Math.hypot(x,y);if(length>1){x/=length;y/=length;}Vec3 offset=a.scale(x*max).add(b.scale(y*max));return new AntiAirGuidanceResolution(p.guidanceTier(),p.perfectInterceptPosition().add(offset),offset,offset.length());}}